INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('MS','published','{"ticker":"MS","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.morganstanley.com/press-releases","description":"Global financial-services firm focused on institutional securities, wealth management, and investment management.","lede":"MORGAN STANLEY earns owner value through advisory and underwriting fees, trading spreads, asset-based fees, net interest income, and investment-management fees. The three questions that matter most are net new assets, fee rate, advisor productivity, lending, and client cash, advisory, underwriting, trading share, backlog, and risk-weighted assets, cet1, stress losses, provisions, liquidity, and shareholder distributions.","sells":"Advisory, underwriting, trading, brokerage, lending, wealth advice, asset management, and alternatives.","revenueModel":"Advisory and underwriting fees, trading spreads, asset-based fees, net interest income, and investment-management fees.","opportunity":"Asset gathering, workplace channels, lending, and capital-markets recovery can deepen recurring pretax profit.","mustGoRight":"Net new assets and fee economics must offset deposit and market pressure while trading, credit, and operational risks remain controlled.","editorNote":"Treat the claimed advantage—a scaled wealth platform can stabilize earnings while institutional franchises monetize capital markets and client flows.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["A scaled wealth platform can stabilize earnings while institutional franchises monetize capital markets and client flows.","Asset gathering, workplace channels, lending, and capital-markets recovery can deepen recurring pretax profit.","Visible progress in wealth assets and institutional securities can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Market and trading risk can weaken the owner outcome; monitor value-at-risk, counterparty exposure, inventory, and loss events.","Wealth cash sorting can weaken the owner outcome; monitor deposit balances, sweep yields, fee waivers, and funding mix.","Regulatory capital can weaken the owner outcome; monitor stress results, buffers, rules, and business constraints.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if wealth-management returns structurally fall and institutional risk produces repeated losses or regulatory capital drag.","financialDrivers":[{"label":"WEALTH ASSETS","value":"Primary owner KPI","detail":"net new assets, fee rate, advisor productivity, lending, and client cash"},{"label":"INSTITUTIONAL SECURITIES","value":"Primary owner KPI","detail":"advisory, underwriting, trading share, backlog, and risk-weighted assets"},{"label":"CAPITAL & CREDIT","value":"Primary owner KPI","detail":"CET1, stress losses, provisions, liquidity, and shareholder distributions"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Market and trading risk","level":"High","text":"Market and trading risk can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"value-at-risk, counterparty exposure, inventory, and loss events"},{"title":"Wealth cash sorting","level":"High","text":"Wealth cash sorting can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"deposit balances, sweep yields, fee waivers, and funding mix"},{"title":"Regulatory capital","level":"High","text":"Regulatory capital can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"stress results, buffers, rules, and business constraints"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"WEALTH ASSETS","text":"Track net new assets, fee rate, advisor productivity, lending, and client cash and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"INSTITUTIONAL SECURITIES","text":"Track advisory, underwriting, trading share, backlog, and risk-weighted assets and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"CAPITAL & CREDIT","text":"Track cet1, stress losses, provisions, liquidity, and shareholder distributions and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies wealth assets?","What would cause institutional securities to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in capital & credit?","Where does MORGAN STANLEY have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"GOLDMAN SACHS GROUP INC, JPMORGAN CHASE & CO, BANK OF AMERICA CORP, CITIGROUP INC, SCHWAB CHARLES CORP, BlackRock, Inc.","comparables":[{"name":"GOLDMAN SACHS GROUP INC","ticker":"GS","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000886982&owner=exclude"},{"name":"JPMORGAN CHASE & CO","ticker":"JPM","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000019617&owner=exclude"},{"name":"BANK OF AMERICA CORP","ticker":"BAC","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000070858&owner=exclude"},{"name":"CITIGROUP INC","ticker":"C","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000831001&owner=exclude"},{"name":"SCHWAB CHARLES CORP","ticker":"SCHW","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000316709&owner=exclude"},{"name":"BlackRock, Inc.","ticker":"BLK","ownership":"Public","relationship":"Operating and valuation reference for MS","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with MS.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0002012383&owner=exclude"}],"sources":[{"title":"MS SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000895421&owner=exclude","excerpt":"MORGAN STANLEY filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"MS annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"MS quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"MS proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"MS investor relations","meta":"Company primary materials","href":"https://www.morganstanley.com/about-us-ir","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"MS official newsroom","meta":"Company announcements","href":"https://www.morganstanley.com/press-releases","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000895421&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://www.morganstanley.com/about-us-ir","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

