INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('ORCL','thesis_breaker','editorial_analysis','If Oracle’s record backlog fails to convert into cash returns above its cost of capital while debt, lease obligations, capital spending, and share issuance continue to expand, the AI cloud transformation would not be creating sufficient value for owners.','Defines evidence that would invalidate the ownership thesis.','Oracle 2026 Form 10-K','https://www.sec.gov/Archives/edgar/data/1341439/000119312526277521/orcl-20260531.htm','The annual filing reports Oracle’s cloud and software mix, revenue, operating cash flow, capital expenditures, cash, debt, property and equipment, lease commitments, revenue recognition, competition, customers, infrastructure obligations, and risk factors.','2026-06-22','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
