INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('ORLY','bear_case','editorial_analysis','Demand for automotive aftermarket parts, tools, accessories, professional repair-shop delivery, and do-it-yourself retail can slow, shift, or become less profitable even when the broader market continues to grow. Recession, fashion, value perception, or weaker experiences can reduce traffic and price. Low switching costs, promotion, or disintermediation can pressure margins. Accounting earnings can overstate owner economics when working capital, capital spending, acquisitions, stock compensation, debt, leases, or dilution absorb cash.','Preserves the skeptical interpretation as a sourced, reviewable claim.','ORLY SEC filing library','https://www.sec.gov/edgar/browse/?CIK=0000898173&owner=exclude','The issuer record provides OREILLY AUTOMOTIVE INC''s filing history, including annual, quarterly, current, proxy, ownership, and registration disclosures.','2026-08-02','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT(ticker,claim,source_url) DO UPDATE SET section=excluded.section,claim_type=excluded.claim_type,why_it_matters=excluded.why_it_matters,source_title=excluded.source_title,source_excerpt=excluded.source_excerpt,evidence_date=excluded.evidence_date,status='published',verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP;

INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('ORLY','thesis_breaker','editorial_analysis','The owner thesis breaks if OREILLY AUTOMOTIVE INC cannot defend its position in automotive aftermarket parts, tools, accessories, professional repair-shop delivery, and do-it-yourself retail and repeatedly fails to convert reported growth into resilient per-share free cash flow after required investment, balance-sheet obligations, and dilution.','Defines evidence that would invalidate the ownership thesis.','ORLY SEC filing library','https://www.sec.gov/edgar/browse/?CIK=0000898173&owner=exclude','The issuer record provides OREILLY AUTOMOTIVE INC''s filing history, including annual, quarterly, current, proxy, ownership, and registration disclosures.','2026-08-02','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
