INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('OTIS','thesis_breaker','editorial_analysis','The owner thesis breaks if OTIS WORLDWIDE CORP cannot defend its position in elevators, escalators, installation, modernization, maintenance contracts, digital monitoring, and building-mobility services and repeatedly fails to convert reported growth into resilient per-share free cash flow after required investment, balance-sheet obligations, and dilution.','Defines evidence that would invalidate the ownership thesis.','OTIS SEC filing library','https://www.sec.gov/edgar/browse/?CIK=0001781335&owner=exclude','The issuer record provides OTIS WORLDWIDE CORP''s filing history, including annual, quarterly, current, proxy, ownership, and registration disclosures.','2026-08-02','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
