INSERT INTO dossier_claims (ticker,section,claim_type,claim,why_it_matters,source_title,source_url,source_excerpt,evidence_date,status,verified_by,verified_at,updated_at)
VALUES ('OXY','thesis_breaker','editorial_analysis','The owner thesis breaks if OCCIDENTAL PETROLEUM CORP cannot defend its position in oil and gas production, chemicals, midstream assets, low-carbon projects, carbon management, and portfolio optimization and repeatedly fails to convert reported growth into resilient per-share free cash flow after required investment, balance-sheet obligations, and dilution.','Defines evidence that would invalidate the ownership thesis.','OXY SEC filing library','https://www.sec.gov/edgar/browse/?CIK=0000797468&owner=exclude','The issuer record provides OCCIDENTAL PETROLEUM CORP''s filing history, including annual, quarterly, current, proxy, ownership, and registration disclosures.','2026-08-02','published','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
