INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('PANW','published','{"ticker":"PANW","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.paloaltonetworks.com/company/press","description":"Cybersecurity platform spanning network, cloud, endpoint, security operations, and threat intelligence.","lede":"PALO ALTO NETWORKS Inc. earns owner value through hardware and software product revenue plus recurring subscriptions, support, cloud consumption, and platform contracts. The three questions that matter most are new platform contracts, renewal, expansion, pricing, and product mix, bookings duration, billing terms, backlog conversion, and cash collections, product adoption, integration, incident outcomes, retention, and support.","sells":"Firewalls, secure access, cloud security, endpoint protection, SOC automation, subscriptions, support, and threat intelligence.","revenueModel":"Hardware and software product revenue plus recurring subscriptions, support, cloud consumption, and platform contracts.","opportunity":"Platformization, cloud workloads, AI security, and vendor consolidation can expand recurring contract value.","mustGoRight":"Large platform deals must produce durable renewal and expansion, product breadth must not dilute quality, and billings must convert to cash.","editorNote":"Treat the claimed advantage—integrated data, distribution, and a broad security platform can consolidate point tools and improve detection and response.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Integrated data, distribution, and a broad security platform can consolidate point tools and improve detection and response.","Platformization, cloud workloads, AI security, and vendor consolidation can expand recurring contract value.","Visible progress in next-gen security arr and remaining obligations can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Competitive disruption can weaken the owner outcome; monitor win rates, pricing, displacement, product gaps, and customer concentration.","Platform deal economics can weaken the owner outcome; monitor discounts, contract duration, billings, renewal, and incremental margin.","Cyber and reliability events can weaken the owner outcome; monitor outages, breaches, vulnerabilities, claims, and remediation.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if platform discounts buy temporary growth but weaken renewal economics while focused competitors take critical workloads.","financialDrivers":[{"label":"NEXT-GEN SECURITY ARR","value":"Primary owner KPI","detail":"new platform contracts, renewal, expansion, pricing, and product mix"},{"label":"REMAINING OBLIGATIONS","value":"Primary owner KPI","detail":"bookings duration, billing terms, backlog conversion, and cash collections"},{"label":"PLATFORM QUALITY","value":"Primary owner KPI","detail":"product adoption, integration, incident outcomes, retention, and support"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Competitive disruption","level":"High","text":"Competitive disruption can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"win rates, pricing, displacement, product gaps, and customer concentration"},{"title":"Platform deal economics","level":"High","text":"Platform deal economics can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"discounts, contract duration, billings, renewal, and incremental margin"},{"title":"Cyber and reliability events","level":"High","text":"Cyber and reliability events can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"outages, breaches, vulnerabilities, claims, and remediation"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"NEXT-GEN SECURITY ARR","text":"Track new platform contracts, renewal, expansion, pricing, and product mix and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"REMAINING OBLIGATIONS","text":"Track bookings duration, billing terms, backlog conversion, and cash collections and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"PLATFORM QUALITY","text":"Track product adoption, integration, incident outcomes, retention, and support and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies next-gen security arr?","What would cause remaining obligations to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in platform quality?","Where does PALO ALTO NETWORKS Inc. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"CrowdStrike Holdings, Inc., Fortinet, Inc., Zscaler, Inc., MICROSOFT CORP, CISCO SYSTEMS, INC., Okta, Inc.","comparables":[{"name":"CrowdStrike Holdings, Inc.","ticker":"CRWD","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001535527&owner=exclude"},{"name":"Fortinet, Inc.","ticker":"FTNT","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001262039&owner=exclude"},{"name":"Zscaler, Inc.","ticker":"ZS","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001713683&owner=exclude"},{"name":"MICROSOFT CORP","ticker":"MSFT","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000789019&owner=exclude"},{"name":"CISCO SYSTEMS, INC.","ticker":"CSCO","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000858877&owner=exclude"},{"name":"Okta, Inc.","ticker":"OKTA","ownership":"Public","relationship":"Operating and valuation reference for PANW","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with PANW.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001660134&owner=exclude"}],"sources":[{"title":"PANW SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0001327567&owner=exclude","excerpt":"Palo Alto Networks Inc filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"PANW