INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('PLTR','published','{"ticker":"PLTR","description":"Data integration and operational software for governments and commercial organizations.","lede":"Palantir’s Gotham, Foundry, Apollo, and AIP platforms connect data, logic, models, and operational decisions across complex customer environments.","sells":"Gotham for government and defense operations, Foundry for enterprise data operations, Apollo for software deployment, and AIP for governed use of artificial intelligence in workflows.","revenueModel":"Multi-period software contracts, subscriptions, platform access, cloud or on-premise deployment, support, and implementation-related services.","opportunity":"Organizations seeking to operationalize AI need governed data, permissions, models, and workflows rather than standalone demonstrations, expanding the potential value of Palantir’s Ontology-centered platforms.","mustGoRight":"AIP adoption must convert into durable production contracts, commercial growth must broaden beyond early cohorts, and deployment economics must scale without customer concentration or excessive customization.","editorNote":"The key distinction is between rapid pilot activity and expanding, recurring production value. Contract growth, remaining deal value, customer count, concentration, margins, and stock-based compensation must be read together.","bullTitle":"AI connected to real operating decisions","bull":["Ontology links data and models to the objects and actions customers operate.","Gotham has deep use across defense and intelligence missions where reliability matters.","AIP can accelerate adoption across both government and commercial customers using the existing platform foundation."],"bearTitle":"High expectations magnify every execution question","bear":["Large government and enterprise contracts can have long, uncertain sales cycles.","Customer concentration and contract timing can make growth uneven.","Cloud vendors, data platforms, consultants, and in-house teams compete for AI and analytics workloads."],"thesisBreaker":"If AIP pilots do not expand into durable production revenue while customer additions and remaining contract value weaken, the platform-growth thesis would require reassessment.","financialDrivers":[{"label":"Q1 REVENUE","value":"$1.6B · +85%","detail":"Growth across U.S. commercial and government; contract timing and termination provisions still matter"},{"label":"GROSS MARGIN","value":"87% GAAP","detail":"Software economics before stock-based compensation, sales investment, and infrastructure requirements"},{"label":"OPERATING INCOME","value":"$754M GAAP","detail":"Compare GAAP with adjusted results and monitor stock-based compensation plus payroll taxes"},{"label":"U.S. REVENUE","value":"+104%","detail":"Company-reported Q1 growth; test customer count, deal size, remaining obligations, and renewal quality"},{"label":"REMAINING DEAL VALUE","value":"Contract visibility","detail":"Firm commitments, termination rights, option periods, contract duration, timing, and customer concentration"},{"label":"DILUTED SHARES","value":"Per-share conversion","detail":"Stock compensation, payroll taxes, repurchases, option exercises, and acquisition issuance"}],"risks":[{"title":"Contract concentration and timing","level":"High","text":"A limited number of large customers and government procurement decisions can affect periods materially.","signal":"Top-customer share, remaining deal value, and award timing"},{"title":"Competitive platform market","level":"High","text":"Customers can combine cloud, data, AI, consulting, and internally developed alternatives.","signal":"Expansion rates and competitive losses"},{"title":"Security and mission sensitivity","level":"High","text":"Failures in security, privacy, availability, or responsible AI controls could impair trust and access.","signal":"Material incidents, contract restrictions, or accreditation delays"},{"title":"Valuation and expectation risk","level":"High","text":"A high implied growth and margin path can produce material downside even when reported operations remain strong.","signal":"Revenue expectations, bookings, margin, cash flow, share count, and implied long-term growth"},{"title":"Deployment and customer concentration","level":"Medium","text":"Complex deployments, large contracts, government procurement, and a limited number of material customers can create timing and renewal volatility.","signal":"Top-customer share, deal duration, deployment labor, renewals, protests, and remaining obligations"}],"monitor":[{"title":"Commercial cohort durability","text":"Track customer growth, contract value, remaining deal value, expansion, renewal, and revenue concentration.","impact":"BULL CASE"},{"title":"Government procurement","text":"Measure program wins and expansion against budget timing, protests, competition, and concentration.","impact":"NEUTRAL"},{"title":"Per-share conversion","text":"Reconcile adjusted profitability to GAAP cash generation and fully diluted share count.","impact":"BEAR CASE"},{"title":"GAAP per-share economics","text":"Reconcile adjusted results with GAAP operating income, stock compensation, payroll taxes, operating cash flow, and diluted shares.","impact":"BEAR CASE"}],"questions":["How repeatable is current U.S. commercial growth once early AI deployments mature?","What portion of bookings can be terminated for convenience or depends on option periods?","Can distribution scale without proportionate deployment and sales labor?","Does per-share value grow after stock-based compensation and dilution?","What contract and deployment characteristics predict durable expansion after the first AI pilot?","What fully diluted share path should owners use when translating company growth into per-share value?"],"competitors":"Microsoft, Amazon Web Services, Google Cloud, Snowflake, Databricks, Salesforce, defense software vendors, systems integrators, and internal development teams.","sources":[{"title":"Palantir SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1321655&owner=exclude","excerpt":"Palantir filings describe its platforms, customer contracts, government and commercial exposure, remaining deal value, stock-based compensation, cash, governance, competition, and risks."},{"title":"Palantir Q1 2026 Results","meta":"Company earnings release · May 4, 2026","href":"https://investors.palantir.com/news-details/2026/Palantir-Reports-Q1-2026-U-S--Revenue-Growth-of-104-YY-and-Revenue-Growth-of-85-YY-Raises-FY-2026-Revenue-Guidance-to-71-YY-Growth-and-U-S--Comm-Revenue-Guidance-to-120-YY-Crushing-Consensus-Expectations/","excerpt":"The official release summarizes first-quarter growth, U.S. revenue trends, and updated company guidance."},{"title":"Palantir Q1 2026 Form 10-Q","meta":"Company-hosted SEC filing","href":"https://investors.palantir.com/files/2026%20Q1%20PLTR%2010-Q.pdf","excerpt":"The filing reports revenue, margins, operating income, cash flow, contract terms, seasonality, share count, contingencies, and risk factors."},{"title":"Palantir Earnings Events","meta":"Company primary materials","href":"https://investors.palantir.com/events.html","excerpt":"Official earnings releases, shareholder letters, presentations, webcasts, and annual or quarterly reports."},{"title":"Palantir Annual Reports","meta":"Company annual filing archive","href":"https://investors.palantir.com/financials/annual-reports","excerpt":"Annual reports provide contract, customer, platform, stock-compensation, governance, liquidity, cash-flow, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investors.palantir.com/news","comparables":[{"name":"Snowflake","ticker":"SNOW","ownership":"Public","relationship":"Enterprise data and AI platform competitor","valuation":"Compare product revenue, remaining obligations, and free cash flow","financialStatus":"High-growth, subscription and consumption software platform with different deployment economics.","sourceUrl":"https://investors.snowflake.com/"},{"name":"Datadog","ticker":"DDOG","ownership":"Public","relationship":"Cloud observability and enterprise software comparable","valuation":"Compare growth, margin, retention, and cash conversion","financialStatus":"Profitable-at-scale cloud software business with a broadening platform.","sourceUrl":"https://investors.datadoghq.com/"},{"name":"C3.ai","ticker":"AI","ownership":"Public","relationship":"Enterprise AI application competitor","valuation":"Revenue multiple must be read with losses and cash","financialStatus":"Smaller enterprise-AI vendor still working toward durable profitability.","sourceUrl":"https://ir.c3.ai/"},{"name":"Anduril","ticker":"—","ownership":"Private","relationship":"Defense software, autonomy, and systems competitor","valuation":"Private; no continuously observable public value","financialStatus":"Venture-backed defense technology company; disclosures are less complete than SEC reporting.","sourceUrl":"https://www.anduril.com/"},{"name":"Microsoft","ticker":"MSFT","ownership":"Public","relationship":"Enterprise data, cloud, AI, security, and developer-platform competitor","valuation":"Compare growth and margin within a much broader platform","financialStatus":"Highly profitable diversified platform with enormous installed-base distribution.","sourceUrl":"https://www.microsoft.com/en-us/Investor/"},{"name":"ServiceNow","ticker":"NOW","ownership":"Public","relationship":"Enterprise workflow, data, automation, and AI comparable","valuation":"Compare subscription growth, remaining obligations, margin, and free cash flow","financialStatus":"Profitable cloud workflow platform with a different deployment and government mix.","sourceUrl":"https://www.servicenow.com/company/investor-relations.html"}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001321655&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001321655&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001321655&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001321655&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.palantir.com/news-details/2026/Palantir-Reports-Q1-2026-U-S--Revenue-Growth-of-104-YY-and-Revenue-Growth-of-85-YY-Raises-FY-2026-Revenue-Guidance-to-71-YY-Growth-and-U-S--Comm-Revenue-Guidance-to-120-YY-Crushing-Consensus-Expectations/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

