INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('RKLB','published','{"ticker":"RKLB","description":"Launch services, spacecraft, satellite components, and space-mission systems.","lede":"Rocket Lab combines the flight-proven Electron launch vehicle with a growing Space Systems portfolio and the capital-intensive development of the larger Neutron rocket.","sells":"Electron and HASTE launches, spacecraft design and manufacturing, satellite components, mission operations, separation systems, solar products, flight software, and future Neutron launch capacity.","revenueModel":"Launch contracts recognized around missions plus product and long-term contract revenue from spacecraft, components, and space systems services.","opportunity":"A vertically integrated supplier can capture more mission value across launch, spacecraft, components, and operations while government and commercial demand for resilient space architectures grows.","mustGoRight":"Electron reliability must remain high, Space Systems programs must execute profitably, Neutron must reach service without exhausting financial capacity, and launch cadence must scale safely.","editorNote":"The existing business and the Neutron option should be valued separately: current segment economics provide evidence, while schedule, cost, and demand assumptions dominate the new-launch thesis.","bullTitle":"More than a small-launch company","bull":["Electron has established flight heritage and a repeat customer base.","Space Systems supplies components and spacecraft regardless of which rocket launches them.","Neutron could expand addressable missions and support an integrated launch-and-spacecraft offering."],"bearTitle":"Space hardware compounds technical and capital risk","bear":["A launch failure can halt cadence, increase cost, and damage customer trust.","Neutron development requires substantial capital before commercial economics are proven.","Government programs and complex spacecraft contracts can shift schedule, scope, and margin."],"thesisBreaker":"A loss of Electron reliability combined with prolonged Neutron delay and weak Space Systems contract economics would undermine the integrated-space-platform thesis.","financialDrivers":[{"label":"Q1 REVENUE","value":"$200.3M · +63.5%","detail":"Launch Services and Space Systems mix; acquisitions and program timing affect comparability"},{"label":"GAAP GROSS MARGIN","value":"38.2%","detail":"Track launch cadence, component mix, contract estimates, and development cost treatment"},{"label":"BACKLOG","value":"$2.2B","detail":"Conversion depends on mission schedules, customer funding, contract terms, and execution"},{"label":"LIQUIDITY","value":">$2B access","detail":"Company-stated access after financing; weigh against Neutron, acquisitions, facilities, and ongoing losses"},{"label":"R&D AND CASH BURN","value":"Funding runway","detail":"Neutron, spacecraft, launch infrastructure, acquisitions, stock compensation, capex, and working capital"},{"label":"CONTRACT MIX","value":"Margin quality","detail":"Firm versus option value, fixed-price exposure, government funding, milestone accounting, and mission timing"}],"risks":[{"title":"Launch reliability","level":"High","text":"Launch vehicles can fail despite extensive testing, affecting schedule, cost, insurance, and reputation.","signal":"Mission anomalies, investigation duration, and return-to-flight evidence"},{"title":"Neutron development","level":"High","text":"A new launch system requires significant engineering, infrastructure, testing, and capital before revenue.","signal":"Engine, stage, pad, and integrated-test milestones versus spending"},{"title":"Contract execution","level":"High","text":"Spacecraft and government programs can carry fixed-price, supply-chain, and milestone risk.","signal":"Backlog revisions and Space Systems gross margin"},{"title":"Neutron schedule and technical execution","level":"High","text":"A new reusable launch system requires engine, structure, stage, pad, software, regulatory, recovery, and production milestones.","signal":"Hot-fire tests, stage tests, pad readiness, licenses, contracted missions, remaining capex, and target-date changes"},{"title":"Mission and contract concentration","level":"High","text":"Launch failures, customer delays, government protests, fixed-price overruns, or spacecraft defects can materially affect results.","signal":"Mission success, backlog concentration, program charges, insurance, and schedule revisions"}],"monitor":[{"title":"Neutron technical milestones","text":"Track testing, pad and factory readiness, regulatory approvals, schedule, contracted launches, and remaining capital—not target dates alone.","impact":"BULL CASE"},{"title":"Electron and HASTE cadence","text":"Measure successful launches, average revenue, manifest quality, range availability, and mission reliability.","impact":"NEUTRAL"},{"title":"Acquisition integration","text":"Test whether acquired components and spacecraft capabilities improve organic growth, margin, and strategic win rates.","impact":"BEAR CASE"},{"title":"Liquidity per milestone","text":"Track cash and financing against Neutron milestones, acquisitions, capex, operating losses, and diluted shares.","impact":"BEAR CASE"}],"questions":["What capital remains before Neutron reaches reliable commercial cadence?","How much backlog is funded, firm, and scheduled versus option value?","Can Space Systems sustain margin as program mix changes?","Do acquisitions increase per-share value after financing and integration costs?","Which Neutron milestones retire the most technical and financing risk?","What portion of backlog is funded, non-cancelable, and protected against cost escalation?"],"competitors":"SpaceX, Firefly Aerospace, United Launch Alliance, Arianespace, Northrop Grumman, satellite component suppliers, and spacecraft prime contractors.","sources":[{"title":"Rocket Lab SEC filing library","meta":"SEC EDGAR · Primary filings","href":"https://www.sec.gov/edgar/browse/?CIK=1819994&owner=exclude","excerpt":"Rocket Lab filings describe launch and space systems revenue, contracts, backlog, liquidity, acquisitions, development spending, competition, and mission risk."},{"title":"Rocket Lab Q1 2026 Results","meta":"Company earnings release · May 7, 2026","href":"https://investors.rocketlabcorp.com/news-releases/news-release-details/rocket-lab-announces-first-quarter-2026-financial-results","excerpt":"The official release reports revenue, margin, backlog, liquidity, launch contracts, acquisitions, and second-quarter guidance."},{"title":"Rocket Lab Q1 2026 Form 10-Q","meta":"Company-hosted SEC filing","href":"https://investors.rocketlabcorp.com/sec-filings/sec-filing/10-q/0001819994-26-000028","excerpt":"The filing provides accounting, liquidity, acquisition, contract, risk, and share-count detail behind the earnings release."},{"title":"Rocket Lab Quarterly Results","meta":"Company primary materials","href":"https://investors.rocketlabcorp.com/financial-information/quarterly-results","excerpt":"Official press releases, presentations, webcasts, and quarterly filings across reporting periods."},{"title":"Rocket Lab Annual Reports","meta":"Company annual filing archive","href":"https://investors.rocketlabcorp.com/financial-information/annual-reports","excerpt":"Annual reports provide segment, backlog, mission, development, acquisition, liquidity, share-count, governance, and risk evidence."}],"reviewed":"August 1, 2026","completeness":100,"newsroomUrl":"https://investors.rocketlabcorp.com/news-releases","comparables":[{"name":"SpaceX","ticker":"—","ownership":"Private","relationship":"Launch, satellite, spacecraft, and government-program competitor","valuation":"Private; transaction values are intermittent and not like-for-like","financialStatus":"Scaled private operator with launch and Starlink economics that are not separately disclosed through SEC filings.","sourceUrl":"https://www.spacex.com/"},{"name":"Northrop Grumman","ticker":"NOC","ownership":"Public","relationship":"Space systems, launch, propulsion, and defense comparable","valuation":"Compare program mix, margins, backlog, and cash conversion","financialStatus":"Large profitable defense prime with mature government programs.","sourceUrl":"https://investor.northropgrumman.com/"},{"name":"Lockheed Martin","ticker":"LMT","ownership":"Public","relationship":"Space, missiles, national-security, and systems competitor","valuation":"Mature-prime multiples are not appropriate for Neutron option value","financialStatus":"Large cash-generative defense prime with long-cycle funded backlog.","sourceUrl":"https://investors.lockheedmartin.com/"},{"name":"L3Harris","ticker":"LHX","ownership":"Public","relationship":"Space payload, propulsion, communications, and defense comparable","valuation":"Compare organic growth, margin, leverage, and cash conversion","financialStatus":"Diversified defense technology supplier integrating major acquired assets.","sourceUrl":"https://www.l3harris.com/investors"},{"name":"Redwire","ticker":"RDW","ownership":"Public","relationship":"Space infrastructure, components, spacecraft, and government-program comparable","valuation":"Compare backlog, acquisition mix, margin, leverage, and cash burn","financialStatus":"Smaller public space platform with meaningful acquisition and program exposure.","sourceUrl":"https://ir.redwirespace.com/"},{"name":"Firefly Aerospace","ticker":"PRIVATE","ownership":"Private","relationship":"Launch, lunar, and spacecraft competitor","valuation":"No continuously observable public valuation","financialStatus":"Private financial statements and complete program economics are unavailable.","sourceUrl":"https://fireflyspace.com/"}],"evidenceReview":{"reviewedAt":"August 1, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001819994&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001819994&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001819994&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0001819994&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.rocketlabcorp.com/news-releases/news-release-details/rocket-lab-announces-first-quarter-2026-financial-results","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

