INSERT INTO company_dossiers (ticker,status,content_json,verified_by,verified_at,published_at,updated_at) VALUES ('RTX','published','{"ticker":"RTX","reviewed":"August 2, 2026","completeness":100,"newsroomUrl":"https://www.rtx.com/news","description":"Aerospace and defense company spanning aircraft engines, avionics, missiles, sensors, space, cyber, and aftermarket services.","lede":"RTX Corp. earns owner value through long-cycle government and commercial contracts, original-equipment sales, cost-plus and fixed-price programs, and aftermarket services. The three questions that matter most are flight hours, shop visits, parts pricing, installed base, and spare engines, awards, funded backlog, mix, deliveries, and program margin, engine inspections, removals, compensation, supplier recovery, and cash cost.","sells":"Commercial and military engines, avionics, mission systems, missiles, radars, sensors, space systems, and maintenance.","revenueModel":"Long-cycle government and commercial contracts, original-equipment sales, cost-plus and fixed-price programs, and aftermarket services.","opportunity":"Commercial flight hours, defense replenishment, modernization, and backlog conversion can drive revenue and cash flow.","mustGoRight":"Powder-metal remediation must remain bounded, suppliers must support output, fixed-price programs must execute, and cash must convert.","editorNote":"Treat the claimed advantage—large installed bases, certified platforms, engineering depth, and classified capabilities can support durable aftermarket and program revenue.—as a thesis to verify against filings, cash conversion, customer behavior, and competitor evidence rather than as an established fact.","bullTitle":"What can compound owner value","bull":["Large installed bases, certified platforms, engineering depth, and classified capabilities can support durable aftermarket and program revenue.","Commercial flight hours, defense replenishment, modernization, and backlog conversion can drive revenue and cash flow.","Visible progress in commercial aftermarket and defense backlog can improve the durability and quality of earnings.","Disciplined reinvestment and capital allocation can convert operating progress into per-share value."],"bearTitle":"What can impair the thesis","bear":["Engine quality and safety can weaken the owner outcome; monitor inspection findings, removals, compensation, regulatory action, and cash charges.","Fixed-price programs can weaken the owner outcome; monitor estimate-at-completion changes, milestones, schedule, and loss provisions.","Supply-chain constraints can weaken the owner outcome; monitor castings, electronics, labor, inventory, and supplier health.","A valuation that assumes flawless execution can fall even when the underlying business remains viable."],"thesisBreaker":"The thesis breaks if quality remediation and program charges repeatedly consume the cash expected from commercial aerospace recovery and defense backlog.","financialDrivers":[{"label":"COMMERCIAL AFTERMARKET","value":"Primary owner KPI","detail":"flight hours, shop visits, parts pricing, installed base, and spare engines"},{"label":"DEFENSE BACKLOG","value":"Primary owner KPI","detail":"awards, funded backlog, mix, deliveries, and program margin"},{"label":"QUALITY REMEDIATION","value":"Primary owner KPI","detail":"engine inspections, removals, compensation, supplier recovery, and cash cost"},{"label":"BALANCE SHEET","value":"Capacity and resilience","detail":"Liquidity, debt, leases, pensions, commitments, interest cost, and refinancing exposure."},{"label":"CASH CONVERSION","value":"Earnings quality","detail":"Operating cash flow, working capital, capital spending, acquisitions, restructuring, and normalized free cash flow."},{"label":"PER-SHARE VALUE","value":"Owner conversion","detail":"Diluted shares, stock compensation, repurchases, dividends, retained earnings, and return on invested capital."}],"risks":[{"title":"Engine quality and safety","level":"High","text":"Engine quality and safety can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"inspection findings, removals, compensation, regulatory action, and cash charges"},{"title":"Fixed-price programs","level":"High","text":"Fixed-price programs can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"estimate-at-completion changes, milestones, schedule, and loss provisions"},{"title":"Supply-chain constraints","level":"High","text":"Supply-chain constraints can materially reduce revenue durability, margins, cash conversion, or the value of invested capital.","signal":"castings, electronics, labor, inventory, and supplier health"},{"title":"Capital allocation","level":"Medium","text":"Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.","signal":"Return on invested capital, leverage, share count, impairment charges, and post-deal performance"},{"title":"Legal, regulatory, and reporting","level":"Medium","text":"Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.","signal":"Proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language"}],"monitor":[{"title":"COMMERCIAL AFTERMARKET","text":"Track flight hours, shop visits, parts pricing, installed base, and spare engines and compare each update with management''s prior commitments.","impact":"BULL CASE"},{"title":"DEFENSE BACKLOG","text":"Track awards, funded backlog, mix, deliveries, and program margin and compare each update with management''s prior commitments.","impact":"NEUTRAL"},{"title":"QUALITY REMEDIATION","text":"Track engine inspections, removals, compensation, supplier recovery, and cash cost and compare each update with management''s prior commitments.","impact":"BEAR CASE"},{"title":"Quarterly thesis audit","text":"Compare each new filing with prior promises and record evidence that strengthens, weakens, or leaves the owner thesis unchanged.","impact":"NEUTRAL"}],"questions":["Which disclosed measure most reliably verifies commercial aftermarket?","What would cause defense backlog to structurally improve or deteriorate?","How should owners separate cyclical movement from durable change in quality remediation?","Where does RTX Corp. have the greatest unpriced customer, supplier, or regulatory dependency?","Which management commitment is most important to verify in the next two reporting periods?","What measurable development would invalidate the owner thesis rather than merely create short-term volatility?"],"competitors":"GENERAL ELECTRIC CO, LOCKHEED MARTIN CORP, NORTHROP GRUMMAN CORP, GENERAL DYNAMICS CORP, BOEING CO, TransDigm Group INC","comparables":[{"name":"GENERAL ELECTRIC CO","ticker":"GE","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000040545&owner=exclude"},{"name":"LOCKHEED MARTIN CORP","ticker":"LMT","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000936468&owner=exclude"},{"name":"NORTHROP GRUMMAN CORP","ticker":"NOC","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001133421&owner=exclude"},{"name":"GENERAL DYNAMICS CORP","ticker":"GD","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000040533&owner=exclude"},{"name":"BOEING CO","ticker":"BA","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0000012927&owner=exclude"},{"name":"TransDigm Group INC","ticker":"TDG","ownership":"Public","relationship":"Operating and valuation reference for RTX","valuation":"Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting, leverage, and capital intensity.","financialStatus":"Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with RTX.","sourceUrl":"https://www.sec.gov/edgar/browse/?CIK=0001260221&owner=exclude"}],"sources":[{"title":"RTX SEC filing library","meta":"SEC EDGAR · Exact filer","href":"https://www.sec.gov/edgar/browse/?CIK=0000101829&owner=exclude","excerpt":"RTX Corp filings provide the audited financial record, business description, material risks, commitments, governance, and current reports."},{"title":"RTX annual reports","meta":"SEC Forms 10-K · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=10-K&owner=exclude&count=40","excerpt":"Annual reports describe the business, segments, competition, financial statements, commitments, controls, and material risks."},{"title":"RTX quarterly reports","meta":"SEC Forms 10-Q · Primary filings","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=10-Q&owner=exclude&count=40","excerpt":"Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion."},{"title":"RTX proxy statements","meta":"SEC DEF 14A · Governance source","href":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=DEF%2014A&owner=exclude&count=40","excerpt":"Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals."},{"title":"RTX investor relations","meta":"Company primary materials","href":"https://investors.rtx.com/","excerpt":"Official earnings releases, presentations, events, governance materials, and shareholder information published by the company."},{"title":"RTX official newsroom","meta":"Company announcements","href":"https://www.rtx.com/news","excerpt":"Official operational, product, partnership, leadership, and corporate announcements; management assertions remain subject to independent verification."}],"evidenceReview":{"reviewedAt":"August 2, 2026","annualFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=10-K&owner=exclude&count=40","quarterlyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=10-Q&owner=exclude&count=40","earningsUpdatesUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=8-K&owner=exclude&count=40","proxyFilingsUrl":"https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=0000101829&type=DEF%2014A&owner=exclude&count=40","officialMaterialsUrl":"https://investors.rtx.com/","transcriptPolicy":"Use an issuer-published transcript when available. Otherwise use the official webcast, prepared remarks, earnings release, and 8-K exhibits; third-party transcripts are secondary and may contain errors."}}','Founding editorial research',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(ticker) DO UPDATE SET status='published',content_json=excluded.content_json,verified_by=excluded.verified_by,verified_at=CURRENT_TIMESTAMP,published_at=COALESCE(company_dossiers.published_at,CURRENT_TIMESTAMP),updated_at=CURRENT_TIMESTAMP;

